WITH flattened_attrs AS (SELECT id, currency, tier_limits, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, ELEMENT_AT(tier_prices, 1) AS entry_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, AGGREGATE(tier_prices, CAST(0 AS DOUBLE), (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ARRAY_MIN(tier_prices) AS lowest_price FROM price_tiers WHERE currency = 'EUR') SELECT *, MAX(lowest_price) OVER (PARTITION BY currency) AS currency_max_lowest_price, LAG(entry_price, 2) OVER (PARTITION BY currency ORDER BY avg_tier_price, id) AS prev_entry_price FROM flattened_attrs
